import {
  google,
  type GoogleLanguageModelInteractionsOptions,
  type GoogleInteractionsVideoOptions,
} from '@ai-sdk/google';
import {
  convertToModelMessages,
  createUIMessageStreamResponse,
  streamText,
  toUIMessageStream,
  type UIMessage,
} from 'ai';

export const maxDuration = 300;

function findLatestInteractionId(messages: UIMessage[]): string | undefined {
  for (let index = messages.length - 1; index >= 0; index--) {
    const message = messages[index];
    if (message.role !== 'assistant') {
      continue;
    }
    for (const part of message.parts) {
      const interactionId = (
        part as {
          providerMetadata?: { google?: { interactionId?: unknown } };
        }
      ).providerMetadata?.google?.interactionId;
      if (typeof interactionId === 'string') {
        return interactionId;
      }
    }
  }
}

function addAgenticVideoProcessing(messages: UIMessage[]): UIMessage[] {
  return messages.map(message => ({
    ...message,
    parts: message.parts.map(part => {
      if (part.type !== 'file' || !part.mediaType.startsWith('video/')) {
        return part;
      }

      return {
        ...part,
        providerMetadata: {
          ...part.providerMetadata,
          google: {
            ...part.providerMetadata?.google,
            processing: 'agentic',
          } satisfies GoogleInteractionsVideoOptions,
        },
      };
    }),
  }));
}

export async function POST(req: Request) {
  const { messages }: { messages: UIMessage[] } = await req.json();
  const previousInteractionId = findLatestInteractionId(messages);
  const modelMessages = await convertToModelMessages(
    addAgenticVideoProcessing(messages),
  );
  const latestUserMessage = modelMessages.findLast(
    message => message.role === 'user',
  );

  const result = streamText({
    model: google.interactions('gemini-3.8-flash'),
    messages:
      previousInteractionId != null && latestUserMessage != null
        ? [latestUserMessage]
        : modelMessages,
    abortSignal: req.signal,
    providerOptions: {
      google: {
        store: true,
        thinkingSummaries: 'auto',
        ...(previousInteractionId != null ? { previousInteractionId } : {}),
      } satisfies GoogleLanguageModelInteractionsOptions,
    },
  });

  return createUIMessageStreamResponse({
    stream: toUIMessageStream({ stream: result.stream }),
  });
}

import type { ElicitationResponse } from './types';

// Use globalThis to ensure the Map is shared across all Next.js API routes
// This prevents issues with module reloading in development
declare global {
  var pendingElicitations:
    | Map<
        string,
        {
          resolve: (response: ElicitationResponse) => void;
          reject: (error: Error) => void;
          createdAt: number;
          timeoutId: NodeJS.Timeout;
        }
      >
    | undefined;
}

// Store pending elicitation requests with their resolvers
const pendingElicitations =
  globalThis.pendingElicitations ??
  new Map<
    string,
    {
      resolve: (response: ElicitationResponse) => void;
      reject: (error: Error) => void;
      createdAt: number;
      timeoutId: NodeJS.Timeout;
    }
  >();

// Persist to globalThis
globalThis.pendingElicitations = pendingElicitations;

// Cleanup old/stale elicitations periodically
function cleanupStaleElicitations() {
  const now = Date.now();
  const staleThreshold = 10 * 60 * 1000; // 10 minutes

  const entries = Array.from(pendingElicitations.entries());
  for (const [id, data] of entries) {
    if (now - data.createdAt > staleThreshold) {
      console.log('[store] Cleaning up stale elicitation:', id);
      clearTimeout(data.timeoutId);
      pendingElicitations.delete(id);
    }
  }
}

// Run cleanup every minute
setInterval(cleanupStaleElicitations, 60 * 1000);

export function createPendingElicitation(
  id: string,
): Promise<ElicitationResponse> {
  console.log('[store] Creating pending elicitation:', id);
  console.log(
    '[store] Current pending IDs:',
    Array.from(pendingElicitations.keys()),
  );
  console.log('[store] Current pending count:', pendingElicitations.size);

  // Check if this ID already exists (shouldn't happen, but handle it)
  if (pendingElicitations.has(id)) {
    console.warn('[store] WARNING: Elicitation ID already exists:', id);
    const existing = pendingElicitations.get(id);
    if (existing) {
      clearTimeout(existing.timeoutId);
      pendingElicitations.delete(id);
    }
  }

  return new Promise<ElicitationResponse>((resolve, reject) => {
    // Set a timeout to prevent hanging indefinitely (60 seconds to match MCP timeout)
    const timeoutId = setTimeout(() => {
      if (pendingElicitations.has(id)) {
        console.log('[store] Timeout for elicitation:', id);
        pendingElicitations.delete(id);
        reject(new Error('Request timed out'));
      }
    }, 60 * 1000);

    pendingElicitations.set(id, {
      resolve,
      reject,
      createdAt: Date.now(),
      timeoutId,
    });
    console.log('[store] Added to map. New count:', pendingElicitations.size);
  });
}

export function resolvePendingElicitation(
  response: ElicitationResponse,
): boolean {
  console.log('[store] Attempting to resolve:', response.id);
  console.log(
    '[store] Current pending IDs:',
    Array.from(pendingElicitations.keys()),
  );

  const pending = pendingElicitations.get(response.id);

  if (!pending) {
    console.log('[store] Not found in map!');
    return false;
  }

  console.log('[store] Found! Resolving...');
  clearTimeout(pending.timeoutId);
  pending.resolve(response);
  pendingElicitations.delete(response.id);
  console.log(
    '[store] Resolved and removed. Remaining count:',
    pendingElicitations.size,
  );
  return true;
}

export function rejectPendingElicitation(id: string, error: Error): boolean {
  console.log('[store] Attempting to reject:', id);
  const pending = pendingElicitations.get(id);

  if (!pending) {
    console.log('[store] Not found in map for rejection!');
    return false;
  }

  console.log('[store] Found! Rejecting...');
  clearTimeout(pending.timeoutId);
  pending.reject(error);
  pendingElicitations.delete(id);
  console.log(
    '[store] Rejected and removed. Remaining count:',
    pendingElicitations.size,
  );
  return true;
}

import { openai } from '@ai-sdk/openai';
import {
  createUIMessageStreamResponse,
  streamText,
  createUIMessageStream,
  convertToModelMessages,
  isStepCount,
  toUIMessageStream,
} from 'ai';
import { createMCPClient, ElicitationRequestSchema } from '@ai-sdk/mcp';
import type { MCPElicitationUIMessage } from './types';
import { createPendingElicitation } from './elicitation-store';

// Allow streaming responses up to 30 seconds
export const maxDuration = 30;

export async function POST(req: Request) {
  const { messages }: { messages: MCPElicitationUIMessage[] } =
    await req.json();

  const stream = createUIMessageStream({
    originalMessages: messages,
    execute: async ({ writer }) => {
      return processMessages(messages, writer);
    },
  });

  return createUIMessageStreamResponse({ stream });
}

async function processMessages(
  messages: MCPElicitationUIMessage[],
  writer: any,
) {
  // Create MCP client with elicitation capabilities
  const mcpClient = await createMCPClient({
    transport: {
      type: 'sse',
      url: 'http://localhost:8085/sse',
    },
    capabilities: {
      elicitation: {},
    },
  });

  // Handle elicitation requests from the MCP server
  mcpClient.onElicitationRequest(ElicitationRequestSchema, async request => {
    const elicitationId = `elicit-${Date.now()}-${Math.random()
      .toString(36)
      .slice(2)}`;

    try {
      // Send elicitation request to the frontend
      writer.write({
        type: 'data-elicitation-request',
        id: elicitationId,
        data: {
          elicitationId,
          message: request.params.message,
          requestedSchema: request.params.requestedSchema,
        },
      });

      // Wait for the user's response (will be resolved via the /respond endpoint)
      const userResponse = await createPendingElicitation(elicitationId);

      // Return the response in the format expected by the MCP server
      return {
        action: userResponse.action,
        content:
          userResponse.action === 'accept' ? userResponse.content : undefined,
      };
    } catch (error) {
      // Return a declined response on error
      return {
        action: 'decline' as const,
      };
    }
  });

  try {
    const tools = await mcpClient.tools();

    const result = streamText({
      model: openai('gpt-6-luna'),
      tools,
      stopWhen: isStepCount(10),
      instructions:
        'You are a helpful assistant. When asked to register a user, use the register_user tool.',
      messages: await convertToModelMessages(messages),
      onEnd: async () => {
        await mcpClient.close();
      },
    });

    writer.merge(
      toUIMessageStream({ stream: result.stream, originalMessages: messages }),
    );
  } catch (error) {
    console.error('Error processing messages:', error);
    await mcpClient.close();
    throw error;
  }
}

import { UIDataTypes, type UIMessage } from 'ai';
export type ElicitationAction = 'accept' | 'decline' | 'cancel';

export interface ElicitationRequest {
  id: string;
  message: string;
  requestedSchema: unknown;
}

export interface ElicitationResponse {
  id: string;
  action: ElicitationAction;
  content?: Record<string, unknown>;
}

// Define custom data types for elicitation
export type ElicitationDataTypes = {
  'elicitation-request': {
    elicitationId: string;
    message: string;
    requestedSchema: unknown;
  };
  'elicitation-response': {
    elicitationId: string;
    action: ElicitationAction;
    content?: Record<string, unknown>;
  };
};

// Define custom message type with elicitation data parts
export type MCPElicitationUIMessage = UIMessage<
  never, // metadata type
  ElicitationDataTypes,
  never // no tools in this example (all tools come from MCP)
>;

import type {
  OAuthClientInformation,
  OAuthClientMetadata,
  OAuthClientProvider,
  OAuthTokens,
} from '@ai-sdk/mcp';
import { randomUUID } from 'node:crypto';

export const sessionCookieName = 'mcp-oauth-session';
export const sessionMaxAge = 30 * 60;

// Each browser session owns one provider for this fixed MCP resource. The SDK
// additionally pins client information and tokens to their authorization issuer.
export class SessionOAuthProvider implements OAuthClientProvider {
  readonly serverUrl = new URL('https://mcp.vercel.com/');
  private savedTokens?: OAuthTokens;
  private savedClientInformation?: OAuthClientInformation;
  private savedCodeVerifier?: string;
  private savedState?: string;
  pendingAuthorization?: { url: string; expiresAt: number };

  constructor(readonly redirectUrl: string) {}

  get clientMetadata(): OAuthClientMetadata {
    return {
      client_name: 'AI SDK MCP OAuth Example (Next.js)',
      redirect_uris: [this.redirectUrl],
      grant_types: ['authorization_code', 'refresh_token'],
      response_types: ['code'],
      token_endpoint_auth_method: 'client_secret_post',
    };
  }

  tokens() {
    return this.savedTokens;
  }

  saveTokens(tokens: OAuthTokens) {
    this.savedTokens = tokens;
  }

  clientInformation() {
    return this.savedClientInformation;
  }

  saveClientInformation(info: OAuthClientInformation) {
    this.savedClientInformation = info;
  }

  isClientInformationDynamicallyRegistered() {
    return true;
  }

  saveCodeVerifier(verifier: string) {
    this.savedCodeVerifier = verifier;
  }

  codeVerifier() {
    if (!this.savedCodeVerifier) throw new Error('No code verifier saved');
    return this.savedCodeVerifier;
  }

  state() {
    return randomUUID();
  }

  saveState(state: string) {
    this.savedState = state;
  }

  storedState() {
    return this.savedState;
  }

  redirectToAuthorization(url: URL) {
    this.pendingAuthorization = {
      url: url.toString(),
      expiresAt: Date.now() + 5 * 60 * 1000,
    };
  }

  clearAuthorization() {
    this.savedState = undefined;
    this.savedCodeVerifier = undefined;
    this.pendingAuthorization = undefined;
  }

  invalidateCredentials(scope: 'all' | 'client' | 'tokens' | 'verifier') {
    if (scope === 'all' || scope === 'tokens') this.savedTokens = undefined;
    if (scope === 'all' || scope === 'client')
      this.savedClientInformation = undefined;
    if (scope === 'all' || scope === 'verifier') this.clearAuthorization();
  }
}

type OAuthSession = {
  origin: string;
  provider: SessionOAuthProvider;
  expiresAt: number;
  busy: boolean;
};

// Local demonstration only: no durable storage or application login system.
// The API rejects hosted/production requests before accessing this store.
const sessions = new Map<string, OAuthSession>();

export function requestOrigin(request: Request) {
  return `${new URL(request.url).protocol}//${request.headers.get('host')}`;
}

export function getOAuthSession(request: Request) {
  for (const [id, session] of sessions) {
    if (session.expiresAt <= Date.now()) sessions.delete(id);
  }

  const cookies = (request.headers.get('cookie') ?? '')
    .split(';')
    .map(cookie => cookie.trim())
    .filter(cookie => cookie.startsWith(`${sessionCookieName}=`));
  if (cookies.length !== 1) return;

  const session = sessions.get(cookies[0].slice(sessionCookieName.length + 1));
  return session?.origin === requestOrigin(request) ? session : undefined;
}

export function createOAuthSession(request: Request) {
  if (sessions.size >= 100) return;

  const id = randomUUID();
  const origin = requestOrigin(request);
  sessions.set(id, {
    origin,
    provider: new SessionOAuthProvider(
      `${origin}/api/chat/mcp-with-auth?callback=1`,
    ),
    expiresAt: Date.now() + sessionMaxAge * 1000,
    busy: false,
  });
  return id;
}

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { auth, type OAuthClientProvider } from '@ai-sdk/mcp';
import { GET, POST } from './route';
import { getOAuthSession } from './oauth-session';

vi.mock('@ai-sdk/mcp', () => ({
  auth: vi.fn(),
  createMCPClient: vi.fn(),
}));

const routeUrl = 'http://localhost:3000/api/chat/mcp-with-auth';

function request(cookie = '', method = 'GET', url = routeUrl) {
  return new Request(url, {
    method,
    headers: {
      host: 'localhost:3000',
      origin: 'http://localhost:3000',
      cookie,
    },
    ...(method === 'POST' ? { body: JSON.stringify({ messages: [] }) } : {}),
  });
}

async function browser() {
  const response = await GET(request());
  const cookie = response.headers.get('set-cookie')!.split(';')[0];
  const session = getOAuthSession(request(cookie))!;
  return { cookie, session };
}

async function consent(provider: OAuthClientProvider) {
  const state = await provider.state!();
  await provider.saveState!(state);
  await provider.saveCodeVerifier('test-verifier');
  const url = new URL('https://authorization.example/authorize');
  url.searchParams.set('state', state);
  url.searchParams.set('redirect_uri', String(provider.redirectUrl));
  await provider.redirectToAuthorization(url);
  return 'REDIRECT' as const;
}

async function send(cookie: string) {
  const response = await POST(request(cookie, 'POST'));
  return { response, body: await response.text() };
}

function callback(state: string) {
  const url = new URL(routeUrl);
  url.searchParams.set('callback', '1');
  url.searchParams.set('state', state);
  url.searchParams.set('code', 'test-code');
  return url.toString();
}

beforeEach(() => {
  vi.stubEnv('NODE_ENV', 'development');
  vi.stubEnv('VERCEL', undefined);
  vi.mocked(auth).mockReset();
  vi.mocked(auth).mockImplementation(consent);
});

afterEach(() => {
  vi.unstubAllEnvs();
  vi.useRealTimers();
});

describe('MCP OAuth callback lifecycle', () => {
  it('rejects anonymous chat requests before starting authorization', async () => {
    const { response } = await send('');
    expect(response.status).toBe(401);
    expect(auth).not.toHaveBeenCalled();
  });

  it('returns independent consent URLs for concurrent browser sessions', async () => {
    const first = await browser();
    const second = await browser();
    const results = await Promise.all([
      send(first.cookie),
      send(second.cookie),
    ]);

    for (const result of results) {
      expect(result.response.status).toBe(200);
      expect(result.body).toContain('data-oauth');
    }
    for (const { session } of [first, second]) {
      const url = new URL(session.provider.pendingAuthorization!.url);
      expect(url.searchParams.get('redirect_uri')).toBe(
        `${routeUrl}?callback=1`,
      );
      expect(session.busy).toBe(false);
    }
    expect(first.session.provider.storedState()).not.toBe(
      second.session.provider.storedState(),
    );
    expect(auth).toHaveBeenCalledTimes(2);
  });

  it('rejects overlapping requests in one session while another session proceeds', async () => {
    const first = await browser();
    const second = await browser();
    let release!: () => void;
    const pending = new Promise<void>(resolve => {
      release = resolve;
    });
    vi.mocked(auth).mockImplementationOnce(async provider => {
      await pending;
      return consent(provider);
    });

    const response = await POST(request(first.cookie, 'POST'));
    try {
      expect((await send(first.cookie)).response.status).toBe(409);
      expect((await send(second.cookie)).body).toContain('data-oauth');
      expect(auth).toHaveBeenCalledTimes(2);
    } finally {
      release();
      await response.text();
    }
    expect(first.session.busy).toBe(false);
  });

  it('reuses pending consent without holding a chat request open', async () => {
    const { cookie, session } = await browser();
    const first = await send(cookie);
    const pending = session.provider.pendingAuthorization;
    const second = await send(cookie);

    expect(first.body).toContain('data-oauth');
    expect(second.body).toContain('data-oauth');
    expect(session.provider.pendingAuthorization).toBe(pending);
    expect(auth).toHaveBeenCalledOnce();
    expect(session.busy).toBe(false);
  });

  it('rejects expired callbacks and starts fresh authorization after five minutes', async () => {
    vi.useFakeTimers({ toFake: ['Date'] });
    const { cookie, session } = await browser();
    await send(cookie);
    const oldState = session.provider.storedState()!;
    vi.setSystemTime(Date.now() + 5 * 60 * 1000);

    const response = await GET(request(cookie, 'GET', callback(oldState)));
    expect(response.status).toBe(400);
    expect(auth).toHaveBeenCalledOnce();
    expect((await send(cookie)).body).toContain('data-oauth');
    expect(auth).toHaveBeenCalledTimes(2);
    expect(session.provider.storedState()).not.toBe(oldState);
    expect(session.busy).toBe(false);
  });

  it('requires the initiating browser session and matching callback state', async () => {
    const first = await browser();
    const second = await browser();
    await send(first.cookie);
    const url = callback(first.session.provider.storedState()!);

    expect((await GET(request('', 'GET', url))).status).toBe(401);
    expect((await GET(request(second.cookie, 'GET', url))).status).toBe(400);
    expect(
      (await GET(request(first.cookie, 'GET', callback('wrong-state')))).status,
    ).toBe(400);
    expect(first.session.provider.pendingAuthorization).toBeDefined();
    expect(auth).toHaveBeenCalledOnce();
  });

  it('consumes a successful callback once and clears state and PKCE', async () => {
    const { cookie, session } = await browser();
    await send(cookie);
    const state = session.provider.storedState()!;
    const url = new URL(callback(state));
    url.searchParams.set('iss', 'https://authorization.example');
    vi.mocked(auth).mockResolvedValueOnce('AUTHORIZED');

    expect((await GET(request(cookie, 'GET', url.toString()))).status).toBe(
      200,
    );
    expect(auth).toHaveBeenLastCalledWith(session.provider, {
      serverUrl: session.provider.serverUrl,
      authorizationCode: 'test-code',
      callbackState: state,
      callbackIssuer: 'https://authorization.example',
    });
    expect(session.provider.pendingAuthorization).toBeUndefined();
    expect(session.provider.storedState()).toBeUndefined();
    expect(() => session.provider.codeVerifier()).toThrow('No code verifier');
    expect(session.busy).toBe(false);
    expect((await GET(request(cookie, 'GET', url.toString()))).status).toBe(
      400,
    );
    expect(auth).toHaveBeenCalledTimes(2);
  });

  it('cleans up denied authorization and allows a retry', async () => {
    const { cookie, session } = await browser();
    await send(cookie);
    const url = new URL(callback(session.provider.storedState()!));
    url.searchParams.set('error', 'access_denied');

    expect((await GET(request(cookie, 'GET', url.toString()))).status).toBe(
      400,
    );
    expect(session.provider.pendingAuthorization).toBeUndefined();
    expect(session.provider.storedState()).toBeUndefined();
    expect(session.busy).toBe(false);
    expect((await send(cookie)).body).toContain('data-oauth');
    expect(auth).toHaveBeenCalledTimes(2);
  });
});

import { openai } from '@ai-sdk/openai';
import {
  convertToModelMessages,
  isStepCount,
  streamText,
  createUIMessageStream,
  createUIMessageStreamResponse,
  toUIMessageStream,
} from 'ai';
import { createMCPClient, auth } from '@ai-sdk/mcp';
import { isLocalDevelopmentRequest } from '../../code-execution-files/is-local-development-request';
import {
  createOAuthSession,
  getOAuthSession,
  sessionCookieName,
  sessionMaxAge,
} from './oauth-session';

const responseHeaders = {
  'Cache-Control': 'no-store',
  'Referrer-Policy': 'no-referrer',
};

function response(message: string, status: number) {
  return new Response(message, { status, headers: responseHeaders });
}

export async function GET(req: Request) {
  const url = new URL(req.url);
  const isCallback = url.searchParams.size > 0;
  // OAuth redirects are cross-site navigations. Keep the loopback/host/proxy
  // checks, then require the initiating browser's cookie AND one-time state.
  const headers = new Headers(req.headers);
  if (isCallback) headers.delete('sec-fetch-site');
  if (!isLocalDevelopmentRequest(new Request(req.url, { headers }))) {
    return response('MCP OAuth is only available in local development.', 403);
  }

  const session = getOAuthSession(req);
  if (!isCallback) {
    if (session) return response('Session ready.', 200);
    const id = createOAuthSession(req);
    if (!id) return response('Too many sessions. Try again later.', 429);
    return new Response('Session ready.', {
      headers: {
        ...responseHeaders,
        'Set-Cookie': `${sessionCookieName}=${id}; HttpOnly; SameSite=Lax; Path=/api/chat/mcp-with-auth; Max-Age=${sessionMaxAge}${url.protocol === 'https:' ? '; Secure' : ''}`,
      },
    });
  }

  if (!session) return response('Session required.', 401);
  if (session.busy)
    return response('Authorization is already in progress.', 409);
  const provider = session.provider;
  const state = url.searchParams.get('state');
  if (
    url.searchParams.get('callback') !== '1' ||
    !state ||
    state !== provider.storedState() ||
    !provider.pendingAuthorization ||
    provider.pendingAuthorization.expiresAt <= Date.now()
  ) {
    return response('Invalid or expired authorization callback.', 400);
  }

  // Consume the pending callback before awaiting the token exchange. Retain
  // state/PKCE until auth() has independently verified them.
  session.busy = true;
  provider.pendingAuthorization = undefined;
  try {
    const code = url.searchParams.get('code');
    if (!code || url.searchParams.has('error')) {
      return response(
        'Authorization was not completed. Retry your message.',
        400,
      );
    }
    const result = await auth(provider, {
      serverUrl: provider.serverUrl,
      authorizationCode: code,
      callbackState: state,
      callbackIssuer: url.searchParams.get('iss') ?? undefined,
    });
    if (result !== 'AUTHORIZED') return response('Authorization failed.', 400);
    return response(
      'Connected. Close this tab and retry your message in the chat.',
      200,
    );
  } catch {
    return response('Authorization failed. Retry your message.', 400);
  } finally {
    provider.clearAuthorization();
    session.busy = false;
  }
}

export async function POST(req: Request) {
  if (!isLocalDevelopmentRequest(req)) {
    return response('MCP OAuth is only available in local development.', 403);
  }
  const session = getOAuthSession(req);
  if (!session) return response('Session required.', 401);
  if (session.busy) return response('A request is already in progress.', 409);
  session.busy = true;

  try {
    const { messages } = await req.json();
    const stream = createUIMessageStream({
      originalMessages: messages,
      execute: async ({ writer }) => {
        const provider = session.provider;
        try {
          if (
            provider.pendingAuthorization &&
            provider.pendingAuthorization.expiresAt <= Date.now()
          ) {
            provider.clearAuthorization();
          }
          // Try saved access tokens first. The transport handles refresh or
          // fresh authorization if the MCP server rejects the token.
          if (
            !provider.tokens()?.access_token &&
            !provider.pendingAuthorization
          ) {
            provider.clearAuthorization();
            const result = await auth(provider, {
              serverUrl: provider.serverUrl,
            });
            if (result !== 'AUTHORIZED' && !provider.pendingAuthorization) {
              throw new Error('Authorization required');
            }
          }
          if (provider.pendingAuthorization) {
            writer.write({
              type: 'data-oauth',
              data: { url: provider.pendingAuthorization.url },
              transient: true,
            });
            return;
          }
          if (!provider.tokens()?.access_token)
            throw new Error('Authorization required');

          const mcpClient = await createMCPClient({
            transport: {
              type: 'http',
              url: provider.serverUrl.toString(),
              authProvider: provider,
            },
          });
          try {
            const tools = await mcpClient.tools();
            const result = streamText({
              model: openai('gpt-6-luna'),
              tools,
              stopWhen: isStepCount(10),
              instructions:
                'You are a helpful assistant with access to protected tools.',
              messages: await convertToModelMessages(messages),
              abortSignal: req.signal,
            });
            writer.merge(
              toUIMessageStream({
                stream: result.stream,
                originalMessages: messages,
              }),
            );
            await result.consumeStream();
          } finally {
            await mcpClient.close();
          }
        } catch (error) {
          // The transport can request consent while connecting or listing tools.
          if (!provider.pendingAuthorization) throw error;
          writer.write({
            type: 'data-oauth',
            data: { url: provider.pendingAuthorization.url },
            transient: true,
          });
        } finally {
          session.busy = false;
        }
      },
    });
    return createUIMessageStreamResponse({ stream, headers: responseHeaders });
  } catch (error) {
    session.busy = false;
    console.error('MCP with auth error:', error);
    return response('Unexpected error.', 500);
  }
}

